problem.solution:
// Create and initialize the ragged array
int[][] familiesPets = new int[3][];
familiesPets[0] = new int[2];  // First family has 2 pets
familiesPets[1] = new int[4];  // Second family has 4 pets
familiesPets[2] = new int[1];  // Third family has 1 pet

// Fill with data
familiesPets[0][0] = 1;  // Dog
familiesPets[0][1] = 1;  // Cat
familiesPets[1][0] = 2;  // Two dogs
familiesPets[1][1] = 1;  // One cat
familiesPets[1][2] = 1;  // One bird
familiesPets[1][3] = 0;  // No fish (but space is allocated)
familiesPets[2][0] = 1;  // One hamster

// Calculate total pets
int totalPets = 0;
for (int i = 0; i < familiesPets.length; i++) {
    for (int j = 0; j < familiesPets[i].length; j++) {
        totalPets += familiesPets[i][j];
    }
}
System.out.println("Total pets: " + totalPets);
